"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7652],{74589:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CannonController","desc":"Drives the manned-cannon experience for the local player: a ProximityPrompt on\\neach placed cannon to mount, plus Stash (hold F) / Move (hold G) prompts from\\n`PlaceableActions.addPrompts` (hidden while it is manned); every turret prompt\\nhides while the local player mans any turret. While mounted, locks movement, shows a ballistic arc\\npreview, and fires on input via ReqFireCannon (server is authoritative). Renders\\nCannonFired (muzzle flash + barrel snap + fire sound) and the cannon explosion\\nsound for all clients. No authoritative state lives here.","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/CannonController.client.luau"}}')}}]);